'use strict';

const fs = require('node:fs/promises');
const path = require('node:path');

const STATUS_URL = process.env.STATUS_URL || 'http://127.0.0.1:54684/status';
const OUTPUT_FILE = path.join(__dirname, 'results', 'status.json');

async function main() {
  const response = await fetch(STATUS_URL);

  if (!response.ok) {
    throw new Error(`GET ${STATUS_URL} failed: ${response.status} ${response.statusText}`);
  }

  const payload = await response.json();

  if (payload.status !== 200) {
    throw new Error(`Unexpected status payload: ${JSON.stringify(payload)}`);
  }

  await fs.mkdir(path.dirname(OUTPUT_FILE), { recursive: true });
  await fs.writeFile(OUTPUT_FILE, `${JSON.stringify(payload)}\n`, 'utf8');

  console.log(`Wrote ${OUTPUT_FILE}: ${JSON.stringify(payload)}`);
}

main().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});

